    import re
    import asyncio

    # 1) Try to dismiss any accessible dialog/modal that might block interaction.
    try:
        dialog = page.get_by_role("dialog")
        if await dialog.count() > 0:
            btns = dialog.get_by_role("button")
            if await btns.count() > 0:
                await btns.first.click()
                await asyncio.sleep(0.2)
    except Exception:
        # Non-fatal, continue
        pass

    # 2) Try to open or focus the site's search UI.
    # Prefer clicking a visible search icon (magnifier) if present, since some themes hide the input.
    try:
        search_icon = page.get_by_role("link", name=re.compile(r"(|search|search icon)", re.IGNORECASE))
        if await search_icon.count() > 0:
            await search_icon.first.click()
            await asyncio.sleep(0.25)
    except Exception:
        # ignore and continue; input may already be visible
        pass

    # 3) Locate the search input: prefer a searchbox, fallback to a textbox.
    search_input = None
    try:
        sb = page.get_by_role("searchbox")
        if await sb.count() > 0:
            search_input = sb.first
    except Exception:
        pass

    if search_input is None:
        try:
            tb = page.get_by_role("textbox")
            if await tb.count() > 0:
                search_input = tb.first
        except Exception:
            pass

