    if search_input is not None:
        # Fill the search term
        await search_input.fill("reveals")

        # 4) Activate the search. Prefer a Search button near the input, else press Enter.
        activated = False
        try:
            # Try to find a button labelled 'Search' near the input by searching globally for a button named search.
            search_button = page.get_by_role("button", name=re.compile(r"search", re.IGNORECASE))
            if await search_button.count() > 0:
                await search_button.first.click()
                activated = True
        except Exception:
            activated = False

        if not activated:
            try:
                # fallback: press Enter in the input
                await search_input.press("Enter")
            except Exception:
                # last fallback: try clicking the first button on the page
                try:
                    all_buttons = page.get_by_role("button")
                    if await all_buttons.count() > 0:
                        await all_buttons.first.click()
                except Exception:
                    pass

    # 5) Wait for results to appear in main (or fallback networkidle)
    main = page.get_by_role("main")
    try:
