    # Always call .count() on locators before using .nth().
    third_article = main.get_by_role("article").nth(2)

    # Prefer link inside heading
    heading_locator = third_article.get_by_role("heading")
    if await heading_locator.count() > 0:
        heading_link = heading_locator.first.get_by_role("link")
